// IPInfo ASN response:
//
// {
//   "name" : "Cloudflare, Inc.",
//   "route" : "1.1.1.0/24",
//   "type" : "hosting",
//   "asn" : "AS13335",
//   "domain" : "cloudflare.com"
// }
public class IPinfoASN {
    private final String name;
    private final String route;
    private final String type;
    private final String asn;
    private final String domain;

    @MaxMindDbConstructor
    public IPinfoASN(@MaxMindDbParameter(name = "name") String name,
                     @MaxMindDbParameter(name = "route") String route,
                     @MaxMindDbParameter(name = "type") String type,
                     @MaxMindDbParameter(name = "asn") String asn,
                     @MaxMindDbParameter(name = "domain") String domain) {
        this.name = name;
        this.route = route;
        this.type = type;
        this.asn = asn;
        this.domain = domain;
    }

    @JsonProperty("name")
    @Nullable
    public String name() {
        return name;
    }

    @JsonProperty("route")
    @Nullable
    public String route() {
        return route;
    }

    @JsonProperty("type")
    @Nullable
    public String type() {
        return type;
    }

    @JsonProperty("asn")
    @Nullable
    public String asn() {
        return asn;
    }

    @JsonProperty("asn_numeric")
    @Nullable
    public Long asnNumeric() {
        final String asnValue = asn();
        if (asnValue == null) {
            return null;
        }
        return Longs.tryParse(asnValue.replace("AS", ""));
    }

    @JsonProperty("domain")
    @Nullable
    public String domain() {
        return domain;
    }
}

